'use strict'

import soundManager from '../service/sound-manager'
import clock from '../service/clock'
import resource from '../resource'
import worldManager from '../service/world-manager'
import { ROOM, isInRoom } from './room-box'
import { overlaps } from '../utils/box'
import { Fireball } from './enemies/projectile'
import { chooseDrop } from './drop'
import { startScream } from './boss-scream'
import { plainName } from './resource/level-colours'
import { reaches, bladeCentre, REACH_BLADE_VERTICAL, REACH_BLADE_SIDEWAYS, FLASH_STEPS, STATE_DYING, STATE_SPAWNING } from './enemies/common'
import { TILE_WIDTH, TILE_HEIGHT, NES_PIXEL, OPPOSITE_DIRECTIONS, DIRECTION_NORTH, DIRECTION_SOUTH, DIRECTION_WEST, DIRECTION_EAST, SOUND_DOOR_UNLOCK, SOUND_SECRET, SOUND_KEY_APPEAR, SOUND_GET_HEART, SOUND_GET_ITEM, SOUND_GET_RUPEE, SOUND_TEXT, SOUND_ENNEMY_DIE, ITEM_KEY, ITEM_FIVE_RUPESS, ITEM_TRIFORCE_FRAGMENT, ENEMY_STALFOS } from '../constant'

// The doors of the rooms of the dungeons, as in the ROM (bank 5, $917C; see docs/rom-analysis.md, Le passage des
// portes). A room (map.room) has the types of its four doors, its event and whether it has a block to push

// Types of the doors (tables 1 and 2 of the room): 2 and 3, the false walls, are walls in the first quest
export const DOOR_OPEN = 0
export const DOOR_BOMB = 4
export const DOOR_LOCKED = 5
export const DOOR_LOCKED_2 = 6
export const DOOR_SHUTTERS = 7

// Events of the rooms (6th table): what opens the shutters
export const EVENT_CLEARED = 1
// The enemy of the first place dead, the others die with it (their $0405 set to $10, as the ghinis of the graves)
export const EVENT_FIRST_KILLS_ALL = 2
export const EVENT_BLOCK = 4
// The block pushed, stairs appear (object $70 at x $D0, y $60: the square 13,2), down to the cellar of the room
export const EVENT_STAIRS = 5
export const EVENT_FIRST_ENEMY = 6
export const EVENT_CLEARED_ITEM = 7

const SIDES = [DIRECTION_NORTH, DIRECTION_SOUTH, DIRECTION_WEST, DIRECTION_EAST]
const VECTORS = { [DIRECTION_NORTH]: [0, -1], [DIRECTION_SOUTH]: [0, 1], [DIRECTION_WEST]: [-1, 0], [DIRECTION_EAST]: [1, 0] }

// Link stays in the room (see room-box.js) or in a doorway, on the axis of the door (x = $78, y = $8D)
const DOOR_X = 7.5 * TILE_WIDTH
const DOOR_Y = 5 * TILE_HEIGHT
// The hole of a wall to bomb, where a bomb opens it (the place of the passage of the door)
const HOLES = { [DIRECTION_NORTH]: [DOOR_X, TILE_HEIGHT], [DIRECTION_SOUTH]: [DOOR_X, 9 * TILE_HEIGHT], [DIRECTION_WEST]: [TILE_WIDTH, DOOR_Y], [DIRECTION_EAST]: [14 * TILE_WIDTH, DOOR_Y] }

// Measured in the ROM, in frames (game steps): Link waits 10 frames at a door he unlocks; the shutters close 10
// frames after he walked in; he pushes a block 17 frames before it moves
const UNLOCK_STEPS = 10
const SHUTTERS_STEPS = 10
const PUSH_STEPS = 17
// He walks in 16 NES pixels by an open or a locked door, 32 by any other (bank 5, $8831); he is carried 32 NES
// pixels out through a bombed wall (bank 5, $B077)
const SHORT_WALK = TILE_HEIGHT
const LONG_WALK = 2 * TILE_HEIGHT
const FRAME = 1000 / 60

const BLOCKING = '11111111'
const FREE = '00000000'
// The passage of the north and south doors: the right half of column 7, the left half of column 8
const RIGHT_FREE = '11000111'
const LEFT_FREE = '01111100'

const isLocked = type => type === DOOR_LOCKED || type === DOOR_LOCKED_2

// What the passage of a door shows: open, closed (lock), sealed (shutters), tunnel (bombed wall), or nothing
// (a wall)
function passage (map, side) {
  const type = map.room.doors[side]
  if (type === DOOR_OPEN) {
    return 'open'
  }
  if (isLocked(type)) {
    return map.openSides.has(side) ? 'open' : 'closed'
  }
  if (type === DOOR_SHUTTERS) {
    return map.shuttersOpen || map.heldOpen === side ? 'open' : 'sealed'
  }
  if (type === DOOR_BOMB && map.openSides.has(side)) {
    return 'tunnel'
  }
}

// Link may walk through: an open door, a door unlocked (once he has waited), open shutters
function canPass (map, side) {
  return passage(map, side) === 'open' && map.unlocking?.side !== side
}

function setTile (map, column, line, name, hitbox) {
  const tile = map.getTile(column, line)
  if (!tile) {
    return
  }
  tile.sprite = resource.getMapSprite(name, map.type) ?? tile.sprite
  tile.setHitbox(hitbox)
}

// The tiles of the doors as their state is (the data of the room has them shut)
export function applyDoors (map) {
  for (const side of SIDES) {
    const shown = passage(map, side)
    if (!shown) {
      continue
    }
    const open = shown === 'open'
    if (side === DIRECTION_NORTH || side === DIRECTION_SOUTH) {
      const [outer, inner] = side === DIRECTION_NORTH ? [0, 1] : [10, 9]
      if (shown === 'tunnel') {
        setTile(map, 7, inner, `dungeon_tunnel_${side}_0`, BLOCKING)
        setTile(map, 8, inner, `dungeon_tunnel_${side}_1`, BLOCKING)
        continue
      }
      setTile(map, 7, outer, `dungeon_door_${side}_top`, open ? RIGHT_FREE : BLOCKING)
      setTile(map, 8, outer, `dungeon_door_${side}_top`, open ? LEFT_FREE : BLOCKING)
      setTile(map, 7, inner, `dungeon_door_${side}_bottom_${shown}_0`, open ? RIGHT_FREE : BLOCKING)
      setTile(map, 8, inner, `dungeon_door_${side}_bottom_${shown}_1`, open ? LEFT_FREE : BLOCKING)
      continue
    }
    const [outer, inner] = side === DIRECTION_WEST ? [0, 1] : [15, 14]
    if (shown === 'tunnel') {
      setTile(map, inner, 5, `dungeon_tunnel_${side}`, BLOCKING)
      continue
    }
    setTile(map, outer, 5, `dungeon_door_${side}_top_1`, open ? FREE : BLOCKING)
    setTile(map, inner, 5, `dungeon_door_${side}_bottom_${shown}`, open ? FREE : BLOCKING)
  }
}

// The room next to this one, through that side
function neighbour (map, side) {
  const [dx, dy] = VECTORS[side]
  return worldManager.getMap(map.type, map.column + dx, map.line + dy)
}

// A door unlocked or a wall blown up stays open, on both sides (the flags of the rooms in the ROM, $06FF + room)
function openForGood (map, side) {
  map.openSides.add(side)
  neighbour(map, side)?.openSides.add(OPPOSITE_DIRECTIONS[side])
  applyDoors(map)
}

// Nothing left to fight: the enemies of the room are dead, the blade traps aside (before they come, those it has)
function isCleared (map) {
  return map.enemiesSpawned ? map.activeEnemies.every(enemy => enemy.isDead || !enemy.mustDie) : map.enemies.length === 0
}

// The event of the room is done: its shutters open
function isEventDone (map) {
  switch (map.room.event) {
    case EVENT_CLEARED:
    case EVENT_CLEARED_ITEM:
      return isCleared(map)
    case EVENT_FIRST_ENEMY:
      return map.enemiesSpawned ? !!map.activeEnemies[0]?.isDead || map.activeEnemies.length === 0 : map.enemies.length === 0
    case EVENT_BLOCK:
      return map.blockPushed
    default:
      return false
  }
}

const hasShutters = map => SIDES.some(side => map.room.doors[side] === DOOR_SHUTTERS)

// Before Link comes in (by the side arrival, if he comes through a door): its shutters are shut, but the one he
// comes through, until the event of the room is done; the block is back in its place
export function prepareRoom (map, arrival) {
  if (!map.room) {
    return
  }
  map.enemiesSpawned = false
  map.blockPushed = false
  map.stairsShown = false
  map.pushSteps = 0
  map.pushedNow = false
  map.unlocking = undefined
  map.crossing = undefined
  map.shuttersOpen = isEventDone(map)
  map.heldOpen = !map.shuttersOpen && map.room.doors[arrival] === DOOR_SHUTTERS ? arrival : undefined
  map.closeSteps = 0
  map.peopleShown = false
  map.peopleSteps = 0
  map.oldManAngry = false
  // Seen on the map of the inventory (bit 5 of the flags of the room, $06FF + room)
  map.visited = true
  applyDoors(map)
}

// The tile of a room visited on the map of the inventory (bank 5, $B608): a bit for each side with a passage, north
// (8), south, west, east (1). An open door, or a locked door or a wall to bomb opened for good; never the shutters,
// whose opening the ROM does not keep ($A689)
const SIDES_ON_MAP = [DIRECTION_NORTH, DIRECTION_SOUTH, DIRECTION_WEST, DIRECTION_EAST]

export function roomPassages (map) {
  return SIDES_ON_MAP.reduce((bits, side) => bits * 2 + (map.room.doors[side] === DOOR_OPEN || map.openSides.has(side) ? 1 : 0), 0)
}

// The old man of a room (measured in $41 of level 1, frames from the one Link stops walking in): he and his flames
// show 2 frames later, with the sound $0602 $08 (bank 1 $8AD3, as any person comes); his text is written from frame
// 27, a character every 4 frames (neither the line break nor the tiles that shift a line take one), each with the
// sound $0604 $10. From the frame he shows to the one of the last character, Link cannot move (frame 155 there)
const PEOPLE_FRAME = 2
const TEXT_FRAME = 27
const LETTER_FRAMES = 4
// Link's highest y with an old man in the room ($8D, line 5 of the room)
const OLD_MAN_LINE = 5 * TILE_HEIGHT

// Struck by the sword (bank 1 $8B00, $04CC), the old man makes his flames spit fireballs at Link, as the statues do
// (bank 4 $8652): at once two from the place of the left flame, then each flame on its own timer ($04E8), drawn
// again when it fires among $50, $80, $F0 and $60 frames (table $8639), or 256 frames once in 16. A flame does not
// fire with Link less than $18 pixels from its place both across and along. Places ($8640, $8648): ($48, $82) and
// ($A8, $86). The fireballs aim at Link and wait 18 frames first; the strike sounds as an enemy killed
const FLAME_PLACES = [[0x48, 0x82], [0xa8, 0x86]]
const FLAME_TIMERS = [0x50, 0x80, 0xf0, 0x60]
const FLAME_LONG_TIMER = 0xff
const FLAME_NEAR = 0x18
const FIREBALL_WAIT = 18
const OBJECT_TOP = 0x3d

function flameTimer (random) {
  const value = Math.floor(random() * 256)
  return value >= 0xf0 ? FLAME_LONG_TIMER : FLAME_TIMERS[value & 3]
}

function spitFireball (map, link, [x, y]) {
  const nx = (link.x - map.x) / NES_PIXEL
  const ny = (link.y - map.y) / NES_PIXEL + OBJECT_TOP
  if (Math.abs(nx - x) < FLAME_NEAR && Math.abs(ny - y) < FLAME_NEAR) {
    return
  }
  map.projectiles.push(new Fireball(map.x + x * NES_PIXEL, map.y + (y - OBJECT_TOP) * NES_PIXEL, link, { wait: FIREBALL_WAIT }))
}

function struck (character, link) {
  const blade = link.getBlade()
  return !!blade && reaches(character, ...bladeCentre(blade.x, blade.y, link.direction), blade.vertical ? REACH_BLADE_VERTICAL : REACH_BLADE_SIDEWAYS)
}

function angryFlames (map, link, random) {
  const character = map.character
  if (character.flashSteps > 0) {
    character.flashSteps--
  }
  if (!map.oldManAngry) {
    if (!map.peopleShown || !struck(character, link)) {
      return
    }
    map.oldManAngry = true
    // He changes palette as an enemy hit ($04F1 from $10, measured)
    character.flashSteps = FLASH_STEPS
    character.flashType = map.type
    soundManager.play(resource.getSound(SOUND_ENNEMY_DIE))
    spitFireball(map, link, FLAME_PLACES[0])
    spitFireball(map, link, FLAME_PLACES[0])
    map.flameTimers = FLAME_PLACES.map(() => flameTimer(random))
    return
  }
  FLAME_PLACES.forEach((place, k) => {
    if (map.flameTimers[k] > 0) {
      map.flameTimers[k]--
      return
    }
    map.flameTimers[k] = flameTimer(random)
    spitFireball(map, link, place)
  })
}

export function updateOldMan (map, link, random = Math.random) {
  const character = map.room && map.character
  if (!character) {
    return
  }
  map.peopleSteps ??= 0
  angryFlames(map, link, random)
  // The first step of the room is frame 0
  const frame = map.peopleSteps++
  if (frame === PEOPLE_FRAME) {
    map.peopleShown = true
    soundManager.play(resource.getSound(SOUND_GET_ITEM))
  }
  const letters = frame - TEXT_FRAME
  if (letters >= 0 && letters % LETTER_FRAMES === 0 && !character.hasStoppedTalking()) {
    // The next character, past a line break
    const text = character.text
    let length = character.displayedText.length + 1
    if (text[length - 1] === '\n') {
      length++
    }
    character.displayedText = text.substring(0, length)
    soundManager.play(resource.getSound(SOUND_TEXT))
  }
}

// The old man shown and his text not all written: Link waits
export function oldManTalking (map) {
  return !!(map.room && map.character && map.peopleShown && !map.character.hasStoppedTalking())
}

// Moves Link a distance his way, at his walking speed, without looking at the scenery
export function walkAlone (link, distance) {
  link.startWalking()
  return new Promise((resolve) => {
    let left = distance
    const timer = clock.repeat(() => {
      left -= link.walkAlone(left)
      if (left <= 0) {
        timer.cancel()
        link.stopWalking()
        resolve()
      }
    }, FRAME)
  })
}

// After the screen scrolled, Link walks into the room on his own: 16 NES pixels by an open or a locked door (he
// stays in the doorway), 32 by any other; then the shutters he came through close
export async function walkIn (map, link) {
  const type = map.room.doors[OPPOSITE_DIRECTIONS[link.direction]]
  await walkAlone(link, type === DOOR_OPEN || isLocked(type) ? SHORT_WALK : LONG_WALK)
  if (map.heldOpen) {
    map.closeSteps = SHUTTERS_STEPS
  }
}

// Through a bombed wall, Link is carried out to the edge of the screen
export function carryOut (link) {
  return walkAlone(link, LONG_WALK)
}

// One game step of the doors: the door being unlocked, the shutters closing behind Link, then opening when the
// event of the room is done; Link stops pushing the block. The enemies die with the first one in a room of event 2
export function updateDoors (map, link) {
  if (!map.room) {
    return
  }
  // Bank 5 $8C28: once the first place is empty (its enemy dead, its death over), the others die, but those still in
  // their cloud or already dying ($0405 + slot not 0); each leaves its item, not counted as killed (measured)
  if (map.room.event === EVENT_FIRST_KILLS_ALL && map.enemiesSpawned) {
    const first = map.activeEnemies.find(enemy => enemy.slot === 1)
    if (!first || first.isDead) {
      for (const enemy of map.activeEnemies) {
        if (enemy !== first && !enemy.isDead && enemy.state !== STATE_DYING && enemy.state !== STATE_SPAWNING) {
          enemy.drop = chooseDrop(enemy.type, link.killRecord, enemy.random, false, enemy.slot, false)
          enemy.setState(STATE_DYING)
        }
      }
    }
  }
  if (map.unlocking && --map.unlocking.steps <= 0) {
    map.unlocking = undefined
  }
  if (map.closeSteps > 0 && --map.closeSteps === 0) {
    map.heldOpen = undefined
    applyDoors(map)
  }
  if (!map.shuttersOpen && hasShutters(map) && isEventDone(map)) {
    map.shuttersOpen = true
    map.heldOpen = undefined
    applyDoors(map)
    soundManager.play(resource.getSound(SOUND_DOOR_UNLOCK))
  }
  if (!map.pushedNow) {
    map.pushSteps = 0
  }
  map.pushedNow = false
}

// Link at (x, y), in a room: true if he is in a doorway he may go through (the scenery is not looked at), false
// if he is out of the room, undefined if the scenery decides (inside the room, or not in a dungeon)
export function roomAllows (map, x, y) {
  if (!map.room) {
    return undefined
  }
  // With an old man, Link stays below his line (measured in $41: y = $8D, wherever across)
  if (map.character && y - map.y < OLD_MAN_LINE) {
    return false
  }
  if (isInRoom(map, x, y)) {
    return undefined
  }
  const rx = x - map.x
  const ry = y - map.y
  let side
  if (rx === DOOR_X) {
    side = ry < ROOM.top ? DIRECTION_NORTH : ry > ROOM.bottom ? DIRECTION_SOUTH : undefined
  } else if (ry === DOOR_Y) {
    side = rx < ROOM.left ? DIRECTION_WEST : rx > ROOM.right ? DIRECTION_EAST : undefined
  }
  return side !== undefined && canPass(map, side)
}

// Link stopped at the edge of the room, on the axis of a door, his way: a locked door opens with a key (or the
// magical key), and he walks through once it is open; through a bombed wall, he is carried
export function tryDoor (map, link) {
  if (!map.room) {
    return
  }
  const side = link.direction
  const rx = link.x - map.x
  const ry = link.y - map.y
  const at = {
    [DIRECTION_NORTH]: rx === DOOR_X && ry === ROOM.top,
    [DIRECTION_SOUTH]: rx === DOOR_X && ry === ROOM.bottom,
    [DIRECTION_WEST]: ry === DOOR_Y && rx === ROOM.left,
    [DIRECTION_EAST]: ry === DOOR_Y && rx === ROOM.right
  }[side]
  if (!at) {
    return
  }
  const type = map.room.doors[side]
  if (isLocked(type) && !map.openSides.has(side)) {
    if (!link.inventory.magicalKey) {
      if (link.inventory.keys <= 0) {
        return
      }
      link.inventory.keys--
    }
    map.unlocking = { side, steps: UNLOCK_STEPS }
    openForGood(map, side)
    soundManager.play(resource.getSound(SOUND_DOOR_UNLOCK))
    return
  }
  if (type === DOOR_BOMB && map.openSides.has(side)) {
    map.crossing = side
  }
}

// A bomb blowing up less than a tile from a wall to bomb opens it, on both sides. True if one opened
export function blowWalls (map, bomb) {
  if (!map.room) {
    return false
  }
  let blown = false
  for (const side of SIDES) {
    if (map.room.doors[side] !== DOOR_BOMB || map.openSides.has(side)) {
      continue
    }
    const [x, y] = HOLES[side]
    if (Math.abs(bomb.x - map.x - x) < TILE_WIDTH && Math.abs(bomb.y - map.y - y) < TILE_HEIGHT) {
      openForGood(map, side)
      blown = true
    }
  }
  if (blown) {
    soundManager.play(resource.getSound(SOUND_SECRET))
  }
  return blown
}

// The block to push: the first block of the middle line of the room, from the left (bank 5, $A808)
export function blockTile (map) {
  for (let column = 2; column <= 13; column++) {
    const tile = map.getTile(column, 5)
    if (tile?.original.sprite?.name?.startsWith('dungeon_block')) {
      return tile
    }
  }
}

// Link pushing the block of the room, once it is cleared (measured): after 17 frames, it slides one tile his
// way, any of the four, if the tile there is free. Once a visit
export function tryPushBlock (map, link) {
  if (!map.room?.block || map.blockPushed || map.pushes.length > 0 || !isCleared(map)) {
    return
  }
  const block = blockTile(map)
  const [dx, dy] = VECTORS[link.direction]
  const hitbox = link.getHitbox()
  const x = dx > 0 ? hitbox.x + hitbox.width : dx < 0 ? hitbox.x - 1 : hitbox.x
  const y = dy > 0 ? hitbox.y + hitbox.height : dy < 0 ? hitbox.y - 1 : hitbox.y
  if (!block || x < block.x || x >= block.x + block.width || y < block.y || y >= block.y + block.height || (dx !== 0 ? link.y !== block.y : link.x !== block.x)) {
    return
  }
  map.pushedNow = true
  map.pushSteps++
  if (map.pushSteps < PUSH_STEPS) {
    return
  }
  const target = map.getTile(block.column + dx, block.line + dy)
  if (!target || target.blockPoints.length > 0) {
    return
  }
  map.pushes.push(new BlockPush(map, block, target, dx, dy))
}

// Coming into a room next to the boss (5th table, bits 5-6: map.room.scream), its scream sounds as Link has walked
// in, and again every 160 frames while he stays (see boss-scream.js), while the boss lives (measured in $45 of level
// 1: the sample $10, not when $35 is cleared)
export function screamOfBoss (map) {
  if (!map.room?.scream) {
    return
  }
  const bossRoom = worldManager[map.type]?.flat().find(room => room?.room?.boss)
  if (bossRoom && !bossRoom.bossKilled) {
    startScream(map.room.scream, map)
  }
}

// The item of the room (5th table, map.room.item; see docs/rom-analysis.md, Dans les donjons), as measured in level
// 1: with event 7, it appears at its place once the room is cleared, with the sound $0602 $02; otherwise it is there
// from the start, at its place, or carried by the enemy of the first place while it lives (it stays where it dies)
// when that enemy is of a type that carries (bank 7, $E6F9: $17, $2A the stalfos, $30; not a wallmaster, a keese or
// a gel). Link takes it by touching it, without holding it up; the room keeps it taken (bit $10 of its flags)
const CARRIERS = [ENEMY_STALFOS]

export function placeRoomItem (map) {
  const item = map.room?.item
  map.roomItem = undefined
  if (!item || map.itemTaken) {
    return
  }
  const x = map.x + item.x * NES_PIXEL
  const y = map.y + item.y * NES_PIXEL
  const hidden = map.room.event === EVENT_CLEARED_ITEM
  const first = map.activeEnemies.find(enemy => enemy.slot === 1)
  map.roomItem = new RoomItem(item.name, x, y, hidden, !hidden && CARRIERS.includes(first?.type) ? first : undefined)
}

// One game step of the item of the room
export function updateRoomItem (map, link) {
  const item = map.roomItem
  if (!item) {
    return
  }
  if (item.hidden) {
    if (!isCleared(map)) {
      return
    }
    item.hidden = false
    soundManager.play(resource.getSound(SOUND_KEY_APPEAR))
  }
  if (item.carrier) {
    if (item.carrier.isDead || !map.activeEnemies.includes(item.carrier)) {
      item.carrier = undefined
    } else {
      item.x = item.carrier.x
      item.y = item.carrier.y
    }
  }
  if (overlaps(item.getBox(), link.getBodyBox())) {
    map.itemTaken = true
    map.roomItem = undefined
    // The piece of the Triforce: Link holds it up, then the level is left (see TriforceTaken)
    if (item.name === ITEM_TRIFORCE_FRAGMENT) {
      map.triforceTaken = item
      return
    }
    link.pickItem(item)
    soundManager.play(resource.getSound(ROOM_ITEM_SOUNDS[item.name] ?? SOUND_GET_ITEM))
  }
}

// The piece of the Triforce changes colours every 8 frames, blue then orange (sprite palettes 1 and 2, measured):
// the frames of its sprite
const TRIFORCE_FLASH = 8 * 1000 / 60

export function triforceImage () {
  return Math.floor(clock.now / TRIFORCE_FLASH) % 2
}

// A key sounds as a heart ($0604 $08), five rupees as a rupee, the others $0602 $08
const ROOM_ITEM_SOUNDS = { [ITEM_KEY]: SOUND_GET_HEART, [ITEM_FIVE_RUPESS]: SOUND_GET_RUPEE }
// Items are 8 NES pixels wide, in the middle of their tile
const ITEM_INSET_X = 8

class RoomItem {
  constructor (name, x, y, hidden, carrier) {
    this.name = name
    this.x = x
    this.y = y
    this.width = TILE_WIDTH
    this.height = TILE_HEIGHT
    this.hidden = hidden
    this.carrier = carrier
  }

  getBox () {
    return { x: this.x + ITEM_INSET_X, y: this.y, width: this.width - 2 * ITEM_INSET_X, height: this.height }
  }

  draw (context) {
    if (!this.hidden) {
      const image = this.name === ITEM_TRIFORCE_FRAGMENT ? triforceImage() : 0
      resource.getSprite(`item_${this.name}`)?.images[image]?.draw(context, this.x, this.y, this.width, this.height)
    }
  }
}

// The stairs of event 5, in their place (see tools/levels/build.js), until Link leaves the room (the block back in its
// place, they are gone)
function showStairs (map) {
  const stairs = map.room.cellar?.stairs
  if (!stairs) {
    return
  }
  const tile = map.getTile(stairs.column, stairs.line)
  // In the palette of the inside of the room (dungeon_floor_p3: dungeon_stairs_p3)
  const palette = /_p\d$/.exec(plainName(tile?.original.sprite?.name ?? ''))?.[0] ?? ''
  setTile(map, stairs.column, stairs.line, `dungeon_stairs${palette}`, tile?.original.hitbox)
  map.stairsShown = true
}

// The block sliding to the next tile, half an NES pixel a frame (measured): one display pixel a game step. In its
// place, it sounds as a secret found ($0602 $04, bank 4 $8278; measured in $22, at the frame it stops)
class BlockPush {
  constructor (map, block, target, dx, dy) {
    this.map = map
    this.block = block
    this.target = target
    this.dx = dx
    this.dy = dy
    this.sprite = block.sprite
    this.offset = 0
    this.done = false
    // Both tiles block while it slides; the one it leaves shows the floor
    block.sprite = target.sprite
    target.setHitbox(block.hitbox)
  }

  process () {
    this.offset++
    if (this.offset < TILE_WIDTH) {
      return
    }
    this.target.sprite = this.sprite
    this.block.setHitbox(this.target.original.hitbox)
    this.map.blockPushed = true
    this.done = true
    soundManager.play(resource.getSound(SOUND_SECRET))
    if (this.map.room.event === EVENT_STAIRS) {
      showStairs(this.map)
    }
  }

  draw (context) {
    this.sprite.draw(context, this.block.x + this.dx * this.offset, this.block.y + this.dy * this.offset, this.block.width, this.block.height)
  }
}
