'use strict'

import InputManager from '../service/input-manager'
import resource from '../resource'
import soundManager from '../service/sound-manager'
import textManager from '../service/text-manager'
import { SLOTS, NAME_LENGTH, emptySlot, slotHearts, slotRing } from '../model/save'
import { NES_PIXEL, SPRITE_TEXT_COLOR_WHITE, SOUND_GET_RUPEE, SOUND_BOMB_DROP, SOUND_LINK_HURT } from '../constant'

// The choice of the game (mode $01), the registration of a name (REGISTER YOUR NAME, mode $0E) and the erasing of a game
// (ELIMINATION MODE, mode $0F), as in the ROM (bank 2, $A591, $9EF0, $9FC5; name tables and sprites measured). Places in
// NES pixels; the 8 lines at the top of the screen are not shown (see title-screen.js)
const FRAME = 1000 / 60
const SCREEN_TOP = 8
const TILE = 8

export const MODE_SELECT = 'select'
export const MODE_REGISTER = 'register'
export const MODE_ELIMINATE = 'eliminate'

// The choice: the 3 games, then REGISTER YOUR NAME (3) and ELIMINATION MODE (4). The heart at x $28, y from $A58C;
// Link of each game (sprites $08 and $0A, his ring's colour) at x $30, y $58 + $18 × game; the name at column 9 of
// line 11 + 3 × game, a dash at column 17, the deaths on 3 digits (column 9, next line), the hearts from column 18
export const REGISTER = 3
export const ELIMINATE = 4
const SELECT_HEART_X = 0x28
const SELECT_HEART_Y = [0x5c, 0x74, 0x8c, 0xa8, 0xb8]
const SELECT_LINK = { x: 0x30, y: 0x58 }
const SLOT_STEP = 0x18
const HEARTS_PER_LINE = 8

// The registration and the erasing: the heart at x $43, y from $9DAF (the 3 games, then END); Link at x $50, y $30 +
// $18 × game; the name at column 14 of line 6 + 3 × game. The letters, 11 a line on 4 lines (table $9DB3), at column
// 6 + 2 × column of line 17 + 2 × line
export const END = 3
const NAME_HEART_X = 0x43
const NAME_HEART_Y = [0x2f, 0x47, 0x5f, 0x77]
const NAME_LINK = { x: 0x50, y: 0x30 }
export const LETTERS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ-.,!\'&.0123456789 '
const LETTERS_PER_LINE = 11
// The cursors (sprite $25, behind the letters, colour $15) show 8 frames, then hide 8 (frame counter $15, bit 3)
const BLINK_FRAMES = 8
// An arrow held moves the cursor of the letters at once, again 16 frames later, then every 8 ($0429)
const REPEAT_FIRST = 16
const REPEAT_NEXT = 8

const ARROWS = {
  [InputManager.ACTION_LINK_MOVE_EAST]: 1,
  [InputManager.ACTION_LINK_MOVE_WEST]: -1,
  [InputManager.ACTION_LINK_MOVE_SOUTH]: LETTERS_PER_LINE,
  [InputManager.ACTION_LINK_MOVE_NORTH]: -LETTERS_PER_LINE
}

function play (name) {
  const sound = resource.getSound(name)
  if (sound) {
    soundManager.play(sound)
  }
}

// The deaths as the ROM writes them ($6E55, $A51E): 3 digits without the zeros in front; 0 for a registered game
export function deathsText (slot) {
  if (!slot.registered) {
    return '   '
  }
  return String(Math.min(255, slot.deaths)).padStart(3, ' ')
}

// The cursor of the letters moved by an arrow: along the 44 letters, or to the line above or below, from one end to
// the other ($A011)
export function moveLetter (letter, step) {
  return (letter + step + LETTERS.length) % LETTERS.length
}

export class FileSelect {
  // slots: the games (see save.js), changed here when a name is registered or a game erased; onChange(slots) keeps
  // them, onPlay(index) starts the game chosen
  constructor (onPlay, onChange) {
    this.onPlay = onPlay
    this.onChange = onChange
    this.visible = false
    this.slots = []
    this.mode = MODE_SELECT
    this.cursor = 0
    this.shownAt = 0
    this.frame = 0
    this.dark = 0
    this.held = new Set()
    this.stopListening = undefined
  }

  // dark: the frames the screen stays black first, the keys doing nothing
  show (slots, now = performance.now(), dark = 0) {
    this.slots = slots
    this.visible = true
    this.shownAt = now
    this.frame = 0
    this.dark = dark
    this.select()
    this.listen()
  }

  hide () {
    this.visible = false
    this.stopListening?.()
    this.stopListening = undefined
  }

  // The keys of the player: Select, Start, A, B and the arrows, pressed and let go
  listen () {
    this.stopListening?.()
    const down = e => {
      const action = this.actionOf(e.code)
      if (!action) {
        return
      }
      e.preventDefault()
      if (e.repeat) {
        return
      }
      this.held.add(action)
      this.press(action)
    }
    const up = e => {
      const action = this.actionOf(e.code)
      if (action) {
        this.held.delete(action)
      }
    }
    document.addEventListener('keydown', down)
    document.addEventListener('keyup', up)
    this.stopListening = () => {
      document.removeEventListener('keydown', down)
      document.removeEventListener('keyup', up)
      this.held.clear()
    }
  }

  actionOf (code) {
    const actions = [InputManager.ACTION_SELECT, InputManager.ACTION_START, InputManager.ACTION_LINK_USE_ITEM_A, InputManager.ACTION_LINK_USE_ITEM_B, ...Object.keys(ARROWS)]
    return actions.find(action => InputManager.getBinding(action) === code)
  }

  press (action) {
    if (this.frame < this.dark) {
      return
    }
    if (action === InputManager.ACTION_SELECT) {
      this.next()
    } else if (action === InputManager.ACTION_START) {
      this.start()
    } else if (action === InputManager.ACTION_LINK_USE_ITEM_A || action === InputManager.ACTION_LINK_USE_ITEM_B) {
      this.type(action === InputManager.ACTION_LINK_USE_ITEM_A)
    } else if (ARROWS[action]) {
      this.arrow = { action, wait: 0, repeated: false }
    }
  }

  // The choice of the game: the heart on the first game registered, or on REGISTER YOUR NAME ($A573)
  select () {
    this.mode = MODE_SELECT
    this.cursor = this.slots.findIndex(slot => slot.registered)
    if (this.cursor === -1) {
      this.cursor = REGISTER
    }
  }

  // REGISTER YOUR NAME: the heart on the first game not registered, or on END; the letters from A
  register () {
    this.mode = MODE_REGISTER
    this.cursor = this.slots.findIndex(slot => !slot.registered)
    if (this.cursor === -1) {
      this.cursor = END
    }
    this.letter = 0
    this.position = 0
    this.arrow = undefined
  }

  eliminate () {
    this.mode = MODE_ELIMINATE
    this.cursor = 0
  }

  // Select: the next choice. On the choice of the game, the games registered, REGISTER YOUR NAME and ELIMINATION
  // MODE ($A5A0); to register, the games not registered and END, the name written from its first letter ($A204); to
  // erase, the 3 games and END. The sound of a rupee each time
  next () {
    play(SOUND_GET_RUPEE)
    if (this.mode === MODE_SELECT) {
      do {
        this.cursor = (this.cursor + 1) % (ELIMINATE + 1)
      } while (this.cursor < SLOTS && !this.slots[this.cursor].registered)
      return
    }
    if (this.mode === MODE_ELIMINATE) {
      this.cursor = (this.cursor + 1) % (END + 1)
      return
    }
    do {
      this.cursor = (this.cursor + 1) % (END + 1)
    } while (this.cursor < SLOTS && this.slots[this.cursor].registered)
    this.position = 0
  }

  // Start: a game chosen, or the registration, or the erasing; to register, on END only: the names written are
  // registered, back to the choice ($9EFF); to erase, a game is erased (sound of Link hurt, $9FE8), END goes to the
  // registration
  start () {
    if (this.mode === MODE_SELECT) {
      if (this.cursor < SLOTS) {
        this.hide()
        this.onPlay(this.cursor)
      } else if (this.cursor === REGISTER) {
        this.register()
      } else {
        this.eliminate()
      }
      return
    }
    if (this.mode === MODE_ELIMINATE) {
      if (this.cursor === END) {
        this.register()
        return
      }
      play(SOUND_LINK_HURT)
      this.slots[this.cursor] = emptySlot()
      this.onChange(this.slots)
      return
    }
    if (this.cursor !== END) {
      return
    }
    for (const slot of this.slots) {
      if (!slot.registered && slot.name.trim() !== '') {
        Object.assign(slot, { registered: true, deaths: 0, game: undefined })
      }
    }
    this.onChange(this.slots)
    this.select()
  }

  // A: the letter of the cursor written in the name (sound of a bomb put down, $A138); B: a letter skipped. The name
  // goes on from its start after the 8th letter
  type (write) {
    if (this.mode !== MODE_REGISTER || this.cursor === END) {
      return
    }
    const slot = this.slots[this.cursor]
    if (write) {
      play(SOUND_BOMB_DROP)
      slot.name = slot.name.slice(0, this.position) + LETTERS[this.letter] + slot.name.slice(this.position + 1)
    }
    this.position = (this.position + 1) % NAME_LENGTH
  }

  // Each frame: the arrow held moves the cursor of the letters (not on END, nor with two arrows held)
  step () {
    this.frame++
    const arrow = this.arrow
    if (!arrow || this.mode !== MODE_REGISTER || this.cursor === END) {
      return
    }
    const arrows = Object.keys(ARROWS).filter(action => this.held.has(action))
    if (arrows.length !== 1 || arrows[0] !== arrow.action) {
      this.arrow = arrows.length === 1 ? { action: arrows[0], wait: 0, repeated: false } : undefined
      if (arrows.length !== 1) {
        return
      }
    }
    if (this.arrow.wait > 0) {
      this.arrow.wait--
      return
    }
    this.letter = moveLetter(this.letter, ARROWS[this.arrow.action])
    this.arrow.wait = this.arrow.repeated ? REPEAT_NEXT : REPEAT_FIRST
    this.arrow.repeated = true
    play(SOUND_GET_RUPEE)
  }

  draw (context, width, height, now = performance.now()) {
    const frame = Math.floor((now - this.shownAt) / FRAME)
    while (this.frame < frame) {
      this.step()
    }
    context.fillStyle = 'black'
    context.fillRect(0, 0, width, height)
    if (this.frame < this.dark) {
      return
    }
    if (this.mode === MODE_SELECT) {
      this.drawSelect(context)
    } else {
      this.drawNames(context)
    }
  }

  tile (context, name, x, y) {
    resource.getSprite(name)?.draw(context, x * NES_PIXEL, (y - SCREEN_TOP) * NES_PIXEL, TILE * NES_PIXEL, TILE * NES_PIXEL)
  }

  text (context, text, column, line) {
    textManager.drawLine(context, text, SPRITE_TEXT_COLOR_WHITE, column * TILE * NES_PIXEL, (line * TILE - SCREEN_TOP) * NES_PIXEL)
  }

  // A line of the frame (tiles $69-$6E, colour $12) from column `from` to column `to`
  line (context, from, to, line) {
    for (let column = from; column <= to; column++) {
      this.tile(context, 'menu_blue_line_horizontal', column * TILE, line * TILE)
    }
  }

  // A frame, without its top line (the titles cut it)
  box (context, left, top, right, bottom) {
    this.tile(context, 'menu_blue_line_corner_north_west', left * TILE, top * TILE)
    this.tile(context, 'menu_blue_line_corner_north_east', right * TILE, top * TILE)
    this.tile(context, 'menu_blue_line_corner_south_west', left * TILE, bottom * TILE)
    this.tile(context, 'menu_blue_line_corner_south_east', right * TILE, bottom * TILE)
    this.line(context, left + 1, right - 1, bottom)
    for (let line = top + 1; line < bottom; line++) {
      this.tile(context, 'menu_blue_line_vertical', left * TILE, line * TILE)
      this.tile(context, 'menu_blue_line_vertical', right * TILE, line * TILE)
    }
  }

  // Link of a game: an 8 × 16 sprite is drawn a line under its y
  link (context, slot, x, y) {
    resource.getSprite(`select_link_${slotRing(slot)}`)?.draw(context, x * NES_PIXEL, (y + 1 - SCREEN_TOP) * NES_PIXEL, 2 * TILE * NES_PIXEL, 2 * TILE * NES_PIXEL)
  }

  heart (context, colour, x, y) {
    this.tile(context, `select_heart_${colour}`, x, y + 1)
  }

  blinkShown () {
    return Math.floor(this.frame / BLINK_FRAMES) % 2 === 1
  }

  drawSelect (context) {
    this.text(context, '- s e l e c t -', 8, 5)
    this.box(context, 3, 8, 28, 25)
    this.line(context, 4, 9, 8)
    this.text(context, ' name ', 10, 8)
    this.line(context, 16, 18, 8)
    this.text(context, ' life ', 19, 8)
    this.line(context, 25, 27, 8)
    this.slots.forEach((slot, k) => {
      const line = 11 + 3 * k
      this.link(context, slot, SELECT_LINK.x, SELECT_LINK.y + SLOT_STEP * k)
      this.text(context, '-', 17, line)
      if (!slot.registered) {
        return
      }
      this.text(context, slot.name, 9, line)
      this.text(context, deathsText(slot), 9, line + 1)
      for (let i = 0; i < slotHearts(slot); i++) {
        this.tile(context, 'select_heart_red', (18 + i % HEARTS_PER_LINE) * TILE, (line + 1 - Math.floor(i / HEARTS_PER_LINE)) * TILE)
      }
    })
    this.text(context, 'register your name', 6, 21)
    this.text(context, 'elimination mode', 6, 23)
    this.heart(context, 'pink', SELECT_HEART_X, SELECT_HEART_Y[this.cursor])
  }

  drawNames (context) {
    const registering = this.mode === MODE_REGISTER
    this.line(context, 4, 7, 3)
    if (registering) {
      this.text(context, 'register your name', 8, 3)
      this.line(context, 26, 28, 3)
      this.text(context, 'register', 10, 15)
    } else {
      this.text(context, 'elimination  mode', 8, 3)
      this.line(context, 25, 28, 3)
      this.text(context, 'elimination', 10, 15)
    }
    this.text(context, 'end', 22, 15)
    this.slots.forEach((slot, k) => {
      this.link(context, slot, NAME_LINK.x, NAME_LINK.y + SLOT_STEP * k)
    })
    // The cursors, behind the letters
    if (registering && this.cursor !== END && this.blinkShown()) {
      this.tile(context, 'select_cursor', 0x70 + TILE * this.position, (6 + 3 * this.cursor) * TILE)
      this.tile(context, 'select_cursor', (6 + 2 * (this.letter % LETTERS_PER_LINE)) * TILE, (17 + 2 * Math.floor(this.letter / LETTERS_PER_LINE)) * TILE)
    }
    this.slots.forEach((slot, k) => {
      if (slot.registered || registering) {
        this.text(context, slot.name, 14, 6 + 3 * k)
      }
    })
    this.box(context, 5, 16, 27, 24)
    this.line(context, 6, 26, 16)
    for (let i = 0; i < LETTERS.length; i++) {
      this.text(context, LETTERS[i], 6 + 2 * (i % LETTERS_PER_LINE), 17 + 2 * Math.floor(i / LETTERS_PER_LINE))
    }
    this.heart(context, registering ? 'pink' : 'white', NAME_HEART_X, NAME_HEART_Y[this.cursor])
  }
}
