'use strict'

import soundManager from '../../service/sound-manager'
import resource from '../../resource'
import { NES_PIXEL, TILE_WIDTH, SOUND_BOSS_HIT, SOUND_ENNEMY_DIE } from '../../constant'
import { stopScream } from '../boss-scream'
import { Enemy, STATE_DYING, STATE_DEAD, STATE_SPAWNING, FLASH_STEPS, WEAPON_BEAM, drawImage, hitCounter } from './common'
import { Fireball } from './projectile'
import { Flyer } from './flyer'

// The gleeok, read in the ROM (objects $42 to $45: 1 to 4 heads, bank 4 $A4DE) and measured in $13 of level 4.
// - Its body does not move: 3 × 2 sprites at x $74, y $57 (tiles of $A809), its image 0, 1, 0, 2 each for 17 frames
//   ($04E6 from $10), each for 7 for 6 images after a head is hit ($04E6 = $0510 = 6).
// - A neck is 5 objects of 6 bytes ($0438 and on: x, y and its counters), from its base (x $7C, y $6F) to its head (y
//   $6F + 5 × each). A neck moves one frame in 4 (the one whose frame counter $15 & 3 is its number): the head goes a
//   NES pixel along each axis, turning back across every 48 moves and up and down every 24 (the first neck at once, the
//   next ones 12, 24, 36 moves later), and the parts between follow it ($A576; transcribed below and checked frame by
//   frame on 1500 frames of the ROM). That frame, a fireball ($56, a heart) may leave its head, when a random byte is
//   under $20 and no fireball flies (slot 11).
// - Only the sword and its beam hit a head; the heads share one life ($0485 + 5): $A0 (10 hits of the wooden sword),
//   then $60 for each next one, with one flash ($04F0 + 5: the body flashes too). A head with no life left is cut
//   ($0511): it flies off (object $46) out of a cloud, and the last one cut kills the gleeok, the flying heads with it,
//   and cuts the scream ($0603 $80). The base of each neck hurts Link too ($79D0), nothing hurts it
const GLEEOK = { life: 0x0a, contactDamage: 1 }
const NEXT_LIFE = 6
const BODY = { x: 0x74, y: 0x57 }
const BASE = { x: 0x7c, y: 0x6f }
const SEGMENT_STEP = 5
const SEGMENTS = 6
const HEAD = 4
// The counters of a neck at the start ($0413-$0418): its turns, its ways (0: +1, $FF: -1), the moves of a step, its
// wait; the necks start 12 moves apart, the even ones going left, the odd ones up
const START_TURNS = [6, 3]
const NECK_WAIT = 12
const MOVES_A_STEP = 4
const ACROSS_STEPS = 12
const ALONG_STEPS = 6
const BODY_FRAMES = 17
const QUICK_BODY_FRAMES = 7
const QUICK_IMAGES = 6
const BODY_IMAGES = [0, 1, 0, 2]
const SHOT_CHANCE = 0x20
const FIREBALL_DAMAGE = 1
const NES_TOP = 0x3d
// The flying head (measured): out of a cloud of 20 frames, it takes off from $BF, 1 more a frame up to $E0 ($04D1:
// 0.875 NES pixel a frame), then flies as a keese that never lands, after Link unless a random byte is $D0 or more
// ($A4BA); its image changes every frame (tiles $EE, $DE)
const FLYING_CLOUD = 20
const FLYING = { life: Infinity, contactDamage: 1, maxSpeed: 0xe0 }
const FLYING_TAKE_OFF = 0xbf
const FLYING_CHANCES = { chase: 0xd0 / 256, land: 0 }

const STATE_STANDING = 'standing'

const byte = value => ((value % 256) + 256) % 256
const signed = value => { const b = byte(value); return b >= 128 ? b - 256 : b }

// The thresholds of $A621 from a quarter of the gap between the base and the head
function limits (gap) {
  const first = Math.min(gap, 4)
  const second = Math.min(first + 4, 8)
  return [first, second, Math.min(second + 4, 11)]
}

// A neck at the start ($A4DE, measured)
export function createNeck (index) {
  return {
    x: Array(SEGMENTS).fill(BASE.x),
    y: Array.from({ length: SEGMENTS }, (_, k) => BASE.y + SEGMENT_STEP * k),
    s: [...START_TURNS, index % 2 === 0 ? 0xff : 0, index % 2 === 0 ? 0 : 0xff, 0, NECK_WAIT * index],
    cut: false
  }
}

// One move of a neck ($A576, then $A7A4 for its head); random: the random byte of the frame ($18)
export function moveNeck (neck, random) {
  const { x, y, s } = neck
  const gap = signed(x[HEAD] - x[0])
  const quarter = gap >= 0 ? gap >> 2 : -((-gap) >> 2)
  const across = limits(Math.abs(quarter))
  const along = limits(Math.abs(signed(y[HEAD] - y[0])) >> 2)
  // Each part not too far from the one before it
  for (let i = 0; i < HEAD; i++) {
    if (Math.abs(signed(x[i] - x[i + 1])) >= across[2]) {
      x[i + 1] = byte(x[i + 1] + (x[i + 1] < x[i] ? 2 : -2))
    }
    if (Math.abs(signed(y[i] - y[i + 1])) >= along[2]) {
      y[i + 1] = byte(y[i + 1] + (y[i + 1] < y[i] ? 2 : -2))
    }
  }
  // The middle parts against the next ones ($A643: the gap across it reads is always 0)
  for (let i = 0; i < HEAD - 1; i++) {
    const height = Math.abs(signed(y[i + 2] - y[i + 1]))
    const kind = (across[0] === 0 ? 1 : 0) + (height >= along[0] ? 3 : 0) + (height >= along[1] ? 3 : 0)
    if (kind === 0) {
      if (random < 0x80) {
        x[i + 1] = byte(x[i + 1] + (x[i + 1] >= x[i + 2] ? 2 : -2))
      } else {
        y[i + 1] = byte(y[i + 1] + (y[i + 1] > y[i + 2] ? 2 : -2))
      }
    } else if (kind >= 6) {
      y[i + 1] = byte(y[i + 1] + (y[i + 1] <= y[i + 2] ? 2 : -2))
    }
  }
  // Across, towards their share of the way to the head
  for (let i = HEAD - 2; i >= 0; i--) {
    const target = byte(x[0] + (i + 1) * quarter)
    x[i + 1] = byte(x[i + 1] + (target >= x[i + 1] ? 1 : -1))
  }
  // Along, between their neighbours
  for (let i = 1; i >= 0; i--) {
    if (y[i + 2] < y[i + 1]) {
      if (y[i + 2] < y[i + 3]) {
        y[i + 2]++
      }
    } else if (y[i + 2] >= y[i + 3]) {
      y[i + 2]--
    }
  }
  // The head
  if (s[5] > 0) {
    s[5]--
    return
  }
  x[HEAD] = byte(x[HEAD] + (s[2] ? -1 : 1))
  y[HEAD] = byte(y[HEAD] + (s[3] ? -1 : 1))
  if (++s[4] < MOVES_A_STEP) {
    return
  }
  s[4] = 0
  if (++s[0] === ACROSS_STEPS) {
    s[0] = 0
    s[2] ^= 0xff
  }
  if (++s[1] === ALONG_STEPS) {
    s[1] = 0
    s[3] ^= 0xff
  }
}

const place = (map, nx, ny) => ({ x: map.x + nx * NES_PIXEL, y: map.y + (ny - NES_TOP) * NES_PIXEL })

export class Gleeok extends Enemy {
  constructor (type, x, y, heads, random = Math.random) {
    super(type, x, y, GLEEOK, random)
    this.width = 3 * TILE_WIDTH / 2
    this.necks = Array.from({ length: heads }, (_, k) => createNeck(k))
    this.frame = 0 // The frame counter of the game ($15), for the turns of the necks
    this.bodyTimer = 0
    this.bodyStep = 0
    this.quickImages = 0
    this.parts = []
    this.setState(STATE_STANDING)
  }

  // The body and its parts: a head and the base of each neck (one base for all: they are at the same place)
  static parts (type, map, heads, random = Math.random) {
    const at = place(map, BODY.x, BODY.y)
    const body = new Gleeok(type, at.x, at.y, heads, random)
    body.map = map
    body.parts = body.necks.map((neck, k) => new GleeokHead(type, body, k, random))
    body.parts.push(new GleeokBase(type, body, random))
    return [body, ...body.parts]
  }

  get isVulnerable () {
    return false
  }

  // Its parts hurt Link
  fight () {}

  // A head hit by the sword or the beam: the life of all the heads goes down; at 0, the head is cut
  headHit (head, link, damage) {
    this.life -= damage
    this.flashSteps = FLASH_STEPS
    this.flashType = link.map?.type
    this.bodyTimer = QUICK_BODY_FRAMES - 1
    this.quickImages = QUICK_IMAGES
    soundManager.play(resource.getSound(SOUND_BOSS_HIT))
    if (this.life > 0) {
      return
    }
    soundManager.play(resource.getSound(SOUND_ENNEMY_DIE))
    this.necks[head.neck].cut = true
    head.setState(STATE_DEAD)
    if (this.necks.every(neck => neck.cut)) {
      this.die(link)
      return
    }
    this.life = NEXT_LIFE
    const flying = new GleeokFlyingHead(head.type, head.x, head.y, this.random)
    flying.slot = head.slot
    this.flying.push(flying)
    head.map?.activeEnemies.push(flying)
  }

  get flying () {
    this.flyingHeads ??= []
    return this.flyingHeads
  }

  // The last head cut: the gleeok dies, its flying heads and its base go
  die () {
    stopScream()
    for (const part of [...this.parts, ...this.flying]) {
      part.setState(STATE_DEAD)
    }
    const base = place(this.map, BASE.x, BASE.y)
    this.x = base.x
    this.y = base.y
    this.width = TILE_WIDTH
    this.setState(STATE_DYING)
  }

  act (map, link) {
    this.map = map
    // The body: its image every 17 frames, every 7 after a hit
    if (this.bodyTimer > 0) {
      this.bodyTimer--
    } else {
      this.bodyStep = (this.bodyStep + 1) % BODY_IMAGES.length
      this.bodyTimer = this.quickImages > 0 ? QUICK_BODY_FRAMES - 1 : BODY_FRAMES - 1
      if (this.quickImages > 0) {
        this.quickImages--
      }
    }
    // The neck of this frame, and maybe a fireball from its head
    const random = Math.floor(this.random() * 256)
    const index = this.frame & 3
    this.frame++
    const neck = this.necks[index]
    if (!neck || neck.cut) {
      return
    }
    moveNeck(neck, random)
    const fireball = map.projectiles.some(projectile => projectile.gleeok && !projectile.done)
    if (Math.floor(this.random() * 256) < SHOT_CHANCE && !fireball) {
      const head = place(map, neck.x[HEAD], neck.y[HEAD])
      const shot = new Fireball(head.x, head.y, link, { damage: FIREBALL_DAMAGE })
      shot.gleeok = true
      map.projectiles.push(shot)
    }
  }

  drawBody (context) {
    drawImage(context, resource.getSprite('gleeok_body'), BODY_IMAGES[this.bodyStep], this.x, this.y, 3 * TILE_WIDTH / 2, 2 * TILE_WIDTH)
    const map = this.map
    if (!map) {
      return
    }
    for (const neck of this.necks.filter(neck => !neck.cut)) {
      for (let k = 0; k < HEAD; k++) {
        const at = place(map, neck.x[k], neck.y[k])
        drawImage(context, resource.getSprite('gleeok_neck_move'), 0, at.x, at.y, TILE_WIDTH / 2, TILE_WIDTH)
      }
    }
  }
}

// The head of a neck, where the neck puts it: hit by the sword or the beam only, as all the heads share their life
class GleeokHead extends Enemy {
  constructor (type, body, neck, random) {
    super(type, body.x, body.y, GLEEOK, random)
    this.body = body
    this.neck = neck
    this.width = TILE_WIDTH / 2
    this.uncounted = true // The gleeok is the enemy of the room
    this.follow()
    this.setState(STATE_STANDING)
  }

  follow () {
    const neck = this.body.necks[this.neck]
    if (this.body.map) {
      const at = place(this.body.map, neck.x[HEAD], neck.y[HEAD])
      this.x = at.x
      this.y = at.y
    }
  }

  // For the weapons, its centre is x + 8 as most enemies' (slot 5 of the ROM, $04BF at 0; measured with the sword up:
  // it reaches from 9 NES pixels left of the head to 15 right of it), though its picture is 8 pixels wide
  get map () {
    return this.body.map
  }

  get mustDie () {
    return false
  }

  get isVulnerable () {
    return this.isActive && hitCounter(this.body.flashSteps) === 0
  }

  stun () {}

  hit (link, { damage, weapon } = {}) {
    if (damage !== undefined && weapon !== WEAPON_BEAM) {
      return
    }
    if (damage === undefined) {
      this.lastSwing = link.swordSwing
    }
    this.body.headHit(this, link, damage ?? link.swordDamage)
  }

  hitByBlade (link) {
    if (!link.getBlade().wand) {
      this.hit(link)
    }
  }

  act () {
    this.follow()
  }

  process (map, link) {
    this.follow()
    this.flashSteps = this.body.flashSteps
    this.flashType = this.body.flashType
    super.process(map, link)
  }

  drawBody (context) {
    drawImage(context, resource.getSprite('gleeok_head_move'), 0, this.x, this.y, TILE_WIDTH / 2, TILE_WIDTH)
  }
}

// The base of the necks: it hurts Link, nothing hurts it
class GleeokBase extends Enemy {
  constructor (type, body, random) {
    const at = body.map ? place(body.map, BASE.x, BASE.y) : { x: body.x, y: body.y }
    super(type, at.x, at.y, GLEEOK, random)
    this.width = TILE_WIDTH / 2
    this.uncounted = true
    this.setState(STATE_STANDING)
  }

  get isVulnerable () {
    return false
  }

  get mustDie () {
    return false
  }

  stun () {}
}

// A head cut off: out of its cloud, it flies over the room until the gleeok dies, spitting fireballs; nothing hurts it
class GleeokFlyingHead extends Flyer {
  constructor (type, x, y, random) {
    super(type, x, y, FLYING, FLYING_CHANCES, random)
    this.cloudSteps = FLYING_CLOUD
    this.setState(STATE_SPAWNING)
    this.frames = 0
    this.uncounted = true
  }

  get isVulnerable () {
    return false
  }

  get mustDie () {
    return false
  }

  stun () {}

  start () {
    this.fly()
    this.takeOff()
    this.speed = FLYING_TAKE_OFF
  }

  act (map, link) {
    this.frames++
    super.act(map, link)
    const fireball = map.projectiles.some(projectile => projectile.gleeok && !projectile.done)
    if (this.frames % 2 === 0 && Math.floor(this.random() * 256) < SHOT_CHANCE && !fireball) {
      const shot = new Fireball(this.x, this.y, link, { damage: FIREBALL_DAMAGE })
      shot.gleeok = true
      map.projectiles.push(shot)
    }
  }

  drawBody (context) {
    drawImage(context, resource.getSprite('gleeok_head_flying'), this.frames % 2, this.x, this.y, this.width, this.height)
  }
}
