'use strict'

import { NES_COLOURS, nesCode } from './resource/nes-colours'
import { MAP_TYPE_WORLD } from '../constant'

// The colours of the screen while Link dies, measured in the ROM: the background palettes 2 and 3 (the scenery)
// turn red, then darken to black in 3 steps; palettes 0 and 1 (white rocks, old man rooms) keep their colours.
// The sprites keep theirs (Link turns grey on his own)
export const DEATH_PALETTES = [
  [0x0f, 0x17, 0x16, 0x26],
  [0x0f, 0x06, 0x17, 0x16],
  [0x0f, 0x07, 0x06, 0x16],
  [0x0f, 0x0f, 0x07, 0x06],
  [0x0f, 0x0f, 0x0f, 0x0f]
]
// Background palettes 0 and 1: the same everywhere
const KEPT_PALETTES = [[0x0f, 0x30, 0x00, 0x12], [0x0f, 0x16, 0x27, 0x36]]
// Background palettes 2 and 3 of the screens, read in the ROM (each dungeon at its entrance)
const SCENERY_PALETTES = {
  [MAP_TYPE_WORLD]: [[0x0f, 0x1a, 0x37, 0x12], [0x0f, 0x17, 0x37, 0x12]],
  level1: [[0x0f, 0x0c, 0x1c, 0x2c], [0x0f, 0x12, 0x1c, 0x2c]],
  level2: [[0x0f, 0x02, 0x12, 0x22], [0x0f, 0x16, 0x12, 0x22]],
  level3: [[0x0f, 0x0b, 0x1b, 0x2b], [0x0f, 0x16, 0x1b, 0x2b]],
  level4: [[0x0f, 0x08, 0x18, 0x28], [0x0f, 0x12, 0x18, 0x28]],
  level5: [[0x0f, 0x0a, 0x1a, 0x2a], [0x0f, 0x16, 0x1a, 0x2a]],
  level6: [[0x0f, 0x08, 0x18, 0x28], [0x0f, 0x16, 0x18, 0x28]],
  level7: [[0x0f, 0x0a, 0x1a, 0x2a], [0x0f, 0x12, 0x1a, 0x2a]],
  level8: [[0x0f, 0x00, 0x10, 0x30], [0x0f, 0x22, 0x10, 0x30]],
  level9: [[0x0f, 0x00, 0x10, 0x30], [0x0f, 0x16, 0x10, 0x30]],
  // The rooms under the levels (measured in $7F of level 1)
  cellar: [[0x0f, 0x00, 0x10, 0x30], [0x0f, 0x00, 0x10, 0x30]]
}
// A colour of the scenery found in none of them (the water of a lake): the brightest of the palette
const OTHER_INDEX = 3
const BLACK = 0x0f

// A piece of the Triforce taken, the scenery flashes: palettes 2 and 3 white (measured)
export const FLASH_PALETTE = [0x0f, 0x30, 0x30, 0x30]

// The NES colours of a tile of a map of this type with palettes 2 and 3 replaced by this one (or each by its own, a
// pair of palettes): code → code, nothing for a tile of palette 0 or 1. colours: the NES colours of the tile;
// palette: the 4 colours of the palette it is drawn with, when known. They tell its palette for sure: its colours
// alone may be of several (a floor of palette 1 all in 16, also a colour of palette 3 at levels 2 and 3, stays
// orange in the ROM while Link dies, measured in $3E of level 2)
function sceneryColours (colours, type, replacement, palette) {
  const scenery = SCENERY_PALETTES[type] ?? SCENERY_PALETTES[MAP_TYPE_WORLD]
  const pair = Array.isArray(replacement[0]) ? replacement : [replacement, replacement]
  const same = codes => palette?.length === codes.length && codes.every((code, i) => code === palette[i])
  if (KEPT_PALETTES.some(same)) {
    return undefined
  }
  const known = scenery.findIndex(same)
  if (known >= 0) {
    return new Map(colours.map(code => [code, palette.includes(code) ? pair[known][palette.indexOf(code)] : code]))
  }
  const inScenery = code => scenery.some(palette => palette.includes(code))
  const kept = KEPT_PALETTES.some(palette => colours.every(code => palette.includes(code)))
  if (kept && !colours.every(inScenery)) {
    return undefined
  }
  // The palette of the tile: the one all its colours are in (the colours shared by both are of palette 2)
  const own = scenery.findIndex(palette => colours.every(code => palette.includes(code)))
  return new Map(colours.map(code => {
    const index = own >= 0 ? own : Math.max(0, scenery.findIndex(p => p.includes(code)))
    const palette = scenery[index]
    return [code, pair[index][palette.includes(code) ? palette.indexOf(code) : OTHER_INDEX]]
  }))
}

// At a step of the death (the palette of the tile: its 4 NES colours, when known)
export function deathColours (colours, type, step, palette) {
  return sceneryColours(colours, type, DEATH_PALETTES[step], palette)
}

// The same, "rrggbb" → "rrggbb" (palette: the 4 "rrggbb" colours of the image, null for none)
export function deathRgb (rgbColours, type, step, palette) {
  return sceneryRgb(rgbColours, type, DEATH_PALETTES[step], palette)
}

// Palettes 2 and 3 replaced, "rrggbb" → "rrggbb". The colour 0 of a palette is the black of the background
export function sceneryRgb (rgbColours, type, replacement, palette) {
  const codes4 = palette?.length === 4 ? palette.map((colour, i) => colour === null || colour === undefined ? (i === 0 ? BLACK : undefined) : nesCode(colour)) : undefined
  const known = codes4?.every(code => code !== undefined) ? codes4 : undefined
  const codes = sceneryColours(rgbColours.map(nesCode).filter(code => code !== undefined), type, replacement, known)
  if (!codes) {
    return undefined
  }
  return new Map(rgbColours.map(colour => [colour, NES_COLOURS[codes.get(nesCode(colour)) ?? nesCode(colour)] ?? colour]))
}
