'use strict'

import soundManager from '../service/sound-manager'
import clock from '../service/clock'
import hitboxManager from '../service/hitbox-manager'
import resource from '../resource'
import { UNIQUE_ITEMS, LINK_ACTION_MOVE, SOUND_FANFARE, LINK_ACTION_PICK, LINK_ACTION_HOLD_UP, SOUND_TEXT_LOOP, SOUND_OVERWORLD, DIRECTION_EAST, DIRECTION_WEST, TRANSITION_MAP_HORIZONTAL_STEP, TRANSITION_MAP_HORIZONTAL_INTERVAL, TRANSITION_MAP_VERTICAL_STEP, TRANSITION_MAP_VERTICAL_INTERVAL, DIRECTION_SOUTH, SOUND_STAIRS, SOUND_LINK_DIE, SOUND_MUSIC_DUNGEON, SOUND_MUSIC_TRIFORCE, SOUND_GET_ITEM, SOUND_TEXT, TILE_WIDTH, TILE_HEIGHT, DIRECTION_NORTH, CAVE_GIFT, RUPEE_COUNT_INTERVAL, DOOR_REPAIR_PRICE, NES_PIXEL } from '../constant'
import { drawMoneyGame, formatSigned } from './cave'
import { INVINCIBLE_STEPS } from './link'
import { heartRefill } from './refill'

class CaveEntrance {
  async play (link) {
    return new Promise((resolve) => {
      link.y += TILE_HEIGHT
      const limitY = link.y - 3 * TILE_HEIGHT
      const transitionTimer = clock.repeat(() => {
        link.startWalking()
        link.y -= 2
        if (link.y <= limitY) {
          transitionTimer.cancel()
          link.stopWalking()
          resolve()
        }
      }, 15)
    })
  }
}

// Out of a cave (measured out of the one of $77, modes $0B, $0A, $04): Link walks down on his own steps (nothing
// walks him) until y = $DD, the bottom line of the cave (see createDynamicMapDragTileTransition), and stops there,
// standing, facing down, still seen 2 frames; then the screen is black (see Game.leaveCave)
const CAVE_EXIT_SEEN_FRAMES = 2

class CaveExit {
  // Not as soon as he steps on the square of the opening: only at the bottom edge
  canStart (link, tile) {
    return link.y >= tile.y
  }

  async play (link) {
    link.direction = DIRECTION_SOUTH
    link.y = link.tile?.y ?? link.y
    link.stopWalking()
    await wait(CAVE_EXIT_SEEN_FRAMES * FRAME)
  }
}

// How far from the stairs Link may still be when he goes down them: his center entering the tile is not
// enough (walking sideways along the wall below a cave door, half of him overlaps the door)
const STAIRS_ALIGNMENT_TOLERANCE = TILE_WIDTH / 4
// Down the stairs and up them (see CaveStairsUp), a NES pixel every 4 frames (measured, mode $10 into level 1 and mode
// $04 out of it), Link behind the scenery (bit 5 of his attribute): seen only through its black, the hole of the stairs
// Into the entrance (measured at level 1, 7,3): Link walks up until he is all on its square (y = $7D, the top half
// of the square stops his feet), only then goes down (mode $10); he stays 2 frames, then sinks a NES pixel every 4
// frames, 16 times, to $8D (62 frames). Off the column of the entrance, the scenery stops him before
const STAIRS_DOWN_WAIT = 2
const STAIRS_DOWN_PIXELS = 16
const STAIRS_DOWN_PIXEL_FRAMES = 4

class CaveStairsDown {
  canStart (link, tile) {
    return Math.abs(link.x - tile.x) <= STAIRS_ALIGNMENT_TOLERANCE && link.y <= tile.y
  }

  async play (link) {
    soundManager.stop(resource.getSound(SOUND_OVERWORLD))
    soundManager.play(resource.getSound(SOUND_STAIRS))
    link.direction = DIRECTION_NORTH
    const tile = link.tile
    link.x = tile.x
    link.y = tile.y
    link.stopWalking()
    const until = framesFrom(clock.now)
    link.behindScenery = true
    link.startWalking()
    for (let pixel = 1; pixel <= STAIRS_DOWN_PIXELS; pixel++) {
      await until(STAIRS_DOWN_WAIT + (pixel - 1) * STAIRS_DOWN_PIXEL_FRAMES)
      link.y = tile.y + pixel * NES_PIXEL
    }
    link.behindScenery = false
    link.stopWalking()
  }
}

// Up the stairs (mode $04, out of a cave or a level; measured out of the cave of $77): Link put a square below
// them, behind the scenery, facing down and walking, with the sound of the stairs ($0603 $08); a NES pixel up the
// next frame, then one every 4 frames, 16 in all: on the square of the stairs 61 frames later, when the music of the
// surface starts again ($0600 $01) and Link may move
const STAIRS_UP_PIXELS = 16
const STAIRS_UP_PIXEL_FRAMES = 4

class CaveStairsUp {
  async play (link) {
    soundManager.play(resource.getSound(SOUND_STAIRS))
    link.direction = DIRECTION_SOUTH
    link.behindScenery = true
    const top = link.y
    link.y = top + TILE_HEIGHT
    link.startWalking()
    const until = framesFrom(clock.now)
    for (let pixel = 1; pixel <= STAIRS_UP_PIXELS; pixel++) {
      await until(1 + (pixel - 1) * STAIRS_UP_PIXEL_FRAMES)
      link.y = top + TILE_HEIGHT - pixel * NES_PIXEL
    }
    link.behindScenery = false
    link.stopWalking()
    soundManager.play(resource.getSound(SOUND_OVERWORLD))
  }
}

// Out of a level by the south door of its entrance, at the bottom edge of the screen: 5 frames later the screen goes
// black and the music stops (measured, modes $06, $07, then $02)
const LEVEL_EXIT_FRAMES = 5

class LevelExit {
  async play (link) {
    link.stopWalking()
    await wait(LEVEL_EXIT_FRAMES * FRAME)
    soundManager.stop(resource.getSound(SOUND_MUSIC_DUNGEON))
  }
}

// The screen of a level or of the surface coming in (mode $03, measured going in and out of level 1, and as the level
// starts again): black, then open from its middle like a curtain, 8 NES pixels more of each side every 5 frames,
// and Link shown 4 frames after it is open. game.curtain is how much of each side is open (NES pixels), -1 for black
// with the top menu
const CURTAIN_STEP = 8
const CURTAIN_STEP_FRAMES = 5
const CURTAIN_HALF = 128
const CURTAIN_LINK_FRAMES = 4
export const CURTAIN_BLACK_FRAMES = 32
export const CURTAIN_RESTART_BLACK_FRAMES = 12

export async function openCurtain (game, blackFrames = CURTAIN_BLACK_FRAMES) {
  game.curtain = -1
  await wait(blackFrames * FRAME)
  for (let open = CURTAIN_STEP; open <= CURTAIN_HALF; open += CURTAIN_STEP) {
    game.curtain = open
    await wait(CURTAIN_STEP_FRAMES * FRAME)
  }
  await wait(CURTAIN_LINK_FRAMES * FRAME)
  game.curtain = undefined
}

// A piece of the Triforce taken, measured in level 1 (frames from the one Link touches it; mode $12): the sound of an
// item, then the music $04 instead of the dungeon's; Link holds it up (16 NES pixels above him) 50 frames, then the
// scenery flashes white 4 frames every 8, 6 times; at frame 98 his hearts fill up as with a fairy, then 134 frames
// later the screen closes from its sides (8 NES pixels a side every 5 frames, the top menu stays), and is black 70
// frames after it began to close, Link still holding the piece; 331 frames after the hearts are full, the top menu
// goes black too and Link leaves the level by its stairs (see Game.leaveLevel)
const TRIFORCE_MUSIC_FRAME = 1
const TRIFORCE_WHITE_FRAMES = [52, 60, 68, 76, 84, 92]
const TRIFORCE_WHITE_LENGTH = 4
const TRIFORCE_REFILL_FRAME = 98
const TRIFORCE_CLOSE_FRAMES = 134
const TRIFORCE_CLOSE_STEPS = 14
const TRIFORCE_BLACK_FRAMES = 204
const TRIFORCE_END_FRAMES = 331
// The frames the hearts take to fill up (1 when they are full)
async function refillHearts (link) {
  const refill = heartRefill(link)
  let frames = 0
  while (!refill.full) {
    await wait(FRAME)
    frames++
    refill.step()
  }
  return Math.max(1, frames)
}

export class TriforceTaken {
  async play (game, item) {
    const link = game.link
    const until = framesFrom(clock.now)
    link.knockback = undefined
    link.usingItem = false
    link.stopWalking()
    link.pickItem(item)
    link.action = LINK_ACTION_HOLD_UP
    game.heldItem = { name: item.name, x: link.x, y: link.y - TILE_HEIGHT }
    soundManager.play(resource.getSound(SOUND_GET_ITEM))
    await until(TRIFORCE_MUSIC_FRAME)
    soundManager.stop(resource.getSound(SOUND_MUSIC_DUNGEON))
    soundManager.play(resource.getSound(SOUND_MUSIC_TRIFORCE))
    for (const frame of TRIFORCE_WHITE_FRAMES) {
      await until(frame)
      game.sceneryFlash = true
      await until(frame + TRIFORCE_WHITE_LENGTH)
      game.sceneryFlash = false
    }
    await until(TRIFORCE_REFILL_FRAME)
    soundManager.play(resource.getSound(SOUND_TEXT))
    const full = TRIFORCE_REFILL_FRAME + await refillHearts(link)
    for (let step = 1; step <= TRIFORCE_CLOSE_STEPS; step++) {
      await until(full + TRIFORCE_CLOSE_FRAMES + (step - 1) * CURTAIN_STEP_FRAMES)
      game.curtain = CURTAIN_HALF - CURTAIN_STEP - step * CURTAIN_STEP
    }
    await until(full + TRIFORCE_BLACK_FRAMES)
    game.curtain = 0
    await until(full + TRIFORCE_END_FRAMES)
    game.heldItem = undefined
    link.action = LINK_ACTION_MOVE
    game.curtain = -1
  }
}

// Direction in which Link crosses to the next screen
const MAP_DRAG_VECTORS = {
  [DIRECTION_EAST]: [1, 0],
  [DIRECTION_NORTH]: [0, -1],
  [DIRECTION_SOUTH]: [0, 1],
  [DIRECTION_WEST]: [-1, 0]
}

class MapDrag {
  // Both maps scroll by exactly one screen while Link walks from the edge he leaves to the opposite
  // edge of the next screen. The last step is left on display (maps scrolled, Link in the coordinates of
  // the screen he leaves): until the game switches maps, the frames drawn show the next screen in
  // place, and the game resets the offsets when it switches (see Game.process). A screen that is not the
  // next one (the whirlwind of the whistle) is shifted by targetShift to come in its place
  async play (link, currentMap, targetMap, targetShift = { x: 0, y: 0 }) {
    const [dx, dy] = MAP_DRAG_VECTORS[link.direction]
    const horizontal = dx !== 0
    const sign = dx + dy
    const distance = horizontal ? currentMap.width : currentMap.height
    const linkSize = horizontal ? link.width : link.height
    const linkFrom = sign > 0 ? distance - linkSize : 0
    const linkTo = distance - linkSize - linkFrom
    const step = horizontal ? TRANSITION_MAP_HORIZONTAL_STEP : TRANSITION_MAP_VERTICAL_STEP
    const interval = horizontal ? TRANSITION_MAP_HORIZONTAL_INTERVAL : TRANSITION_MAP_VERTICAL_INTERVAL
    const nbTicks = Math.round(distance / step)

    let tick = 0
    const update = () => {
      const progress = tick / nbTicks
      const offset = -sign * distance * progress
      const linkPosition = linkFrom + (linkTo - linkFrom) * progress
      if (horizontal) {
        currentMap.offsetX = offset
        targetMap.offsetX = targetShift.x + offset
        targetMap.offsetY = targetShift.y
        link.x = currentMap.x + linkPosition
      } else {
        currentMap.offsetY = offset
        targetMap.offsetY = targetShift.y + offset
        targetMap.offsetX = targetShift.x
        link.y = currentMap.y + linkPosition
      }
    }

    update()
    link.startWalking()
    return new Promise((resolve) => {
      const transitionTimer = clock.repeat(() => {
        tick++
        update()
        if (tick >= nbTicks) {
          transitionTimer.cancel()
          link.stopWalking()
          resolve()
        }
      }, interval)
    })
  }
}

// Rupees counted one at a time, up or down, between 0 and what the wallet holds; Link goes on meanwhile. Each one
// with the sound of a letter of a text ($0604 = $10 every 2 frames, measured buying a potion)
function countRupees (link, delta) {
  let left = Math.abs(delta)
  if (left === 0) {
    return
  }
  const step = Math.sign(delta)
  const timer = clock.repeat(() => {
    soundManager.play(resource.getSound(SOUND_TEXT))
    link.inventory.rupees = Math.max(0, Math.min(link.inventory.maxRupees, link.inventory.rupees + step))
    left--
    if (left === 0) {
      timer.cancel()
    }
  }, RUPEE_COUNT_INTERVAL)
}

// The rupee of a secret cave: the moblin stays, the amount shows under the rupee, nothing is held up
class SecretRupees {
  play (link, item) {
    countRupees(link, item.rupees)
    item.pickable = false
    item.label = item.rupees.toString()
    link.map.emptied = true
  }
}

// The door repair: Link pays as he comes in (all he has if it is not enough, measured in the ROM), once
class DoorRepair {
  play (link) {
    countRupees(link, -Math.min(DOOR_REPAIR_PRICE, link.inventory.rupees))
    link.map.emptied = true
  }
}

// The money making game: every rupee shows what it hid, Link gets or loses what is under his
class MoneyGame {
  play (link, item, random) {
    const values = drawMoneyGame(random)
    link.map.items.forEach((other, i) => {
      other.pickable = false
      other.label = formatSigned(values[i])
    })
    countRupees(link, values[link.map.items.indexOf(item)])
  }
}

// Pay to talk: the prices go, the rupees stay, and what Link paid decides the answer
class PayToTalk {
  play (link, item) {
    countRupees(link, -item.price)
    for (const other of link.map.items) {
      other.pickable = false
      other.label = undefined
    }
    link.map.character?.say(item.text ?? '')
  }
}

class ItemPick {
  buy (link, item) {
    countRupees(link, -item.price)
  }

  removeItemFromMap (map, item) {
    const index = map.items.indexOf(item)
    if (index > -1) {
      map.items.splice(index, 1)
    }
  }

  addItemToMap (map, item) {
    map.items.push(item)
  }

  play (link, item) {
    if (item.price) {
      this.buy(link, item)
    }

    if (link.map.character) {
      link.map.character.vanish(1300)
    }

    const clonedItem = item.clone()
    clonedItem.price = undefined
    clonedItem.label = undefined
    for (const i of link.map.items) {
      i.enabled = false
    }

    // Test picking item or not
    /* if (false) {
      this.finalizeTransition(link.map, item)
      return
    } */

    link.stopWalking()
    link.action = LINK_ACTION_PICK
    this.addItemToMap(link.map, clonedItem)

    const itemCenterX = hitboxManager.getHorizontalCenter(clonedItem.hitbox)
    const itemDeltaX = itemCenterX - clonedItem.x
    clonedItem.x = link.x - itemDeltaX + 4
    clonedItem.y = link.y - clonedItem.height
    // In a cellar, the fanfare ($0600 $08) is played instead of the music of the dungeon, which starts again after it
    // (measured in $7F of level 1: 79 frames)
    const inCellar = !!link.map.cellar
    if (inCellar) {
      soundManager.stop(resource.getSound(SOUND_MUSIC_DUNGEON))
    }
    soundManager.play(resource.getSound(SOUND_FANFARE))

    const self = this
    return new Promise((resolve) => {
      clock.delay(() => {
        link.action = LINK_ACTION_MOVE
        self.removeItemFromMap(link.map, clonedItem)
        self.finalizeTransition(link, item)
        if (inCellar) {
          soundManager.play(resource.getSound(SOUND_MUSIC_DUNGEON))
        }
        resolve()
      }, 1300)
    })
  }

  finalizeTransition (link, item) {
    link.pickItem(item)
    // Taken once: the cave or the cellar is empty from then on
    if (UNIQUE_ITEMS.includes(item.name) || link.map.cave === CAVE_GIFT || link.map.cellar) {
      link.map.emptied = true
      link.map.items = []
      link.map.characters = []
    }
  }
}

class Dialog {
  async play (link) {
    let length = 0
    soundManager.play(resource.getSound(SOUND_TEXT_LOOP))
    return new Promise((resolve) => {
      const transitionTimer = clock.repeat(() => {
        length++
        link.map.character.displayedText = link.map.character.text.substring(0, length)
        if (link.map.character.displayedText === link.map.character.text) {
          soundManager.stop(resource.getSound(SOUND_TEXT_LOOP))
          transitionTimer.cancel()
          resolve()
        }
      }, 50)
    })
  }
}

// Death of Link, measured in the ROM (in frames, 60 per second, from the fatal hit)
const FRAME = 1000 / 60
// Link flashes as when he is hurt, still on the screen as it was
const DEATH_FLASH_FRAMES = 34
const DEATH_RED_FRAME = 62
// Then he spins, a quarter turn every 5 frames, 4 times round, to face down again
const DEATH_SPIN_ORDER = [DIRECTION_SOUTH, DIRECTION_EAST, DIRECTION_NORTH, DIRECTION_WEST]
const DEATH_SPIN_FRAMES = 5
const DEATH_SPIN_TURNS = 16
// The scenery darkens (see death-colours.js), the frames each step starts at
const DEATH_DARKEN_FRAMES = [141, 151, 161, 171]
const DEATH_GREY_FRAME = 172
// His sparkle (sprite link_death): 10 frames, then 4
const DEATH_SPARKLE_FRAMES = [196, 206]
const DEATH_HIDDEN_FRAME = 210
const DEATH_GAME_OVER_FRAME = 256
const DEATH_END_FRAME = 351

function wait (duration) {
  return new Promise((resolve) => clock.delay(resolve, duration))
}

// Waits until frame n from the start: the clock goes by steps of a frame added up, so a little before the exact time,
// or the rounding of the sums would put it a frame later
const FRAME_MARGIN = 0.5
function framesFrom (start) {
  return frame => wait(start + frame * FRAME - FRAME_MARGIN - clock.now)
}

// The screen freezes, the enemies vanish and the music stops. Link flashes, the scenery turns red and Link spins,
// the scenery darkens to black, Link turns grey, becomes a sparkle and vanishes, then GAME OVER. The steps are
// published in game.deathEffect, which Game.draw follows (palette: step of the colours of the scenery)
class Death {
  async play (game) {
    const link = game.link
    soundManager.stop(resource.getSound(SOUND_OVERWORLD))
    soundManager.stop(resource.getSound(SOUND_MUSIC_DUNGEON))
    soundManager.play(resource.getSound(SOUND_LINK_DIE))
    game.map.clearEnemies()
    link.knockback = undefined
    link.usingItem = false
    link.stillSteps = 0
    link.poseSteps = 0
    link.action = LINK_ACTION_MOVE
    link.standStill()

    const effect = { palette: undefined, grey: false, sparkleFrame: undefined, hidden: false, gameOver: false }
    game.deathEffect = effect
    // Each step at its frame from the fatal hit (waits that follow one another would drift)
    const until = framesFrom(clock.now)

    link.invincibleSteps = INVINCIBLE_STEPS
    const flashTimer = clock.repeat(() => { link.invincibleSteps-- }, FRAME)
    await until(DEATH_FLASH_FRAMES)
    flashTimer.cancel()
    link.invincibleSteps = 0

    await until(DEATH_RED_FRAME)
    effect.palette = 0
    link.direction = DIRECTION_SOUTH
    for (let turn = 1; turn <= DEATH_SPIN_TURNS; turn++) {
      await until(DEATH_RED_FRAME + 1 + (turn - 1) * DEATH_SPIN_FRAMES)
      link.direction = DEATH_SPIN_ORDER[turn % DEATH_SPIN_ORDER.length]
    }

    for (const [step, start] of DEATH_DARKEN_FRAMES.entries()) {
      await until(start)
      effect.palette = step + 1
    }
    await until(DEATH_GREY_FRAME)
    effect.grey = true
    link.dead = true

    for (const [sparkleFrame, start] of DEATH_SPARKLE_FRAMES.entries()) {
      await until(start)
      effect.sparkleFrame = sparkleFrame
    }
    await until(DEATH_HIDDEN_FRAME)
    effect.sparkleFrame = undefined
    effect.hidden = true

    await until(DEATH_GAME_OVER_FRAME)
    effect.gameOver = true
    await until(DEATH_END_FRAME)
  }
}

export { CaveEntrance, CaveExit, CaveStairsDown, CaveStairsUp, LevelExit, MapDrag, Dialog, ItemPick, SecretRupees, DoorRepair, MoneyGame, PayToTalk, Death }
