'use strict'

// The sprite sheet is indexed: each pixel holds a colour index (0 to 3, as a grey level), or
// nothing (alpha 0). A sprite of the data gives the colours of the indices:
//   palette: one palette for every frame
//   framePalettes: one palette per frame (a blinking item)
//   palettes: named palettes, one sprite each, its name with "{palette}" replaced by the palette name
// A palette is 4 colours, "rrggbb" or null (transparent). A frame is 16x16 NES pixels, or
// width x height (in NES pixels: size for a square), from its offset (in 16 pixel cells)

const PALETTE_PLACEHOLDER = '{palette}'
const INDEX_GREY_STEP = 85
const DEFAULT_SIZE = 16

// The sprites of the data, with the colours of each frame; variant: rank of the palette among the
// named palettes of the entry (each variant is painted in its own copy of the sheet)
export function expandSprites (entries) {
  const sprites = []
  for (const entry of entries) {
    const width = entry.width ?? entry.size ?? DEFAULT_SIZE
    const height = entry.height ?? entry.size ?? DEFAULT_SIZE
    const variants = entry.palettes
      ? Object.entries(entry.palettes).map(([name, palette]) => [entry.name.replace(PALETTE_PLACEHOLDER, name), entry.offsets.map(() => palette)])
      : [[entry.name, entry.offsets.map((_, i) => entry.framePalettes ? entry.framePalettes[i] : entry.palette)]]
    variants.forEach(([name, palettes], variant) => {
      sprites.push({ name, type: entry.type, width, height, variant, frames: entry.offsets.map((offset, i) => ({ x: offset.x, y: offset.y, palette: palettes[i] })) })
    })
  }
  return sprites
}

const rgbOf = colour => [0, 2, 4].map(i => parseInt(colour.slice(i, i + 2), 16))

// RGBA pixels of one frame: its pixels of the sheet (offset in cells of cellSize pixels) with its colours
export function paintFrame (sheet, sheetWidth, frame, width, height, cellSize) {
  const colours = frame.palette.map(colour => colour === null ? null : rgbOf(colour))
  const pixels = new Uint8ClampedArray(width * height * 4)
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const k = ((frame.y * cellSize + y) * sheetWidth + frame.x * cellSize + x) * 4
      if (sheet[k + 3] === 0) {
        continue
      }
      const colour = colours[Math.round(sheet[k] / INDEX_GREY_STEP)]
      if (!colour) {
        continue
      }
      const d = (y * width + x) * 4
      pixels[d] = colour[0]
      pixels[d + 1] = colour[1]
      pixels[d + 2] = colour[2]
      pixels[d + 3] = 255
    }
  }
  return pixels
}
