'use strict'

import resource from '../resource'
import { overlaps } from '../utils/box'
import { TILE_WIDTH, TILE_HEIGHT, NES_PIXEL, MAP_TYPE_WORLD, MAP_TYPES_LEVELS, DIRECTION_NORTH, DIRECTION_SOUTH } from '../constant'

// Crossing the water with the ladder and the raft, as in the ROM (see docs/rom-analysis.md)

const isVertical = direction => direction === DIRECTION_NORTH || direction === DIRECTION_SOUTH

// The ladder (object $5F, bank 7 $F281): on the overworld, only on the screens of the table $F20D; in the levels,
// over their water. Link walking into a square of water puts it down there, one tile in front of him; he goes over
// it along its way only, and it is gone once he is off it. One square of water only: the next one stops him
const LADDER_SCREENS = ['7,1', '8,1', '9,1', '7,2', '15,4', '15,5']

function isWater (map, tile) {
  const name = tile?.sprite?.name ?? ''
  if (map.type === MAP_TYPE_WORLD) {
    return LADDER_SCREENS.includes(`${map.column},${map.line}`) && /(^|_)water/.test(name)
  }
  return MAP_TYPES_LEVELS.includes(map.type) && name.startsWith('dungeon_water')
}

// Link was stopped going that way: the ladder goes down on the water in front of him, if he has it
export function tryPutLadder (map, link, direction, front) {
  if (!link.inventory.ladder || map.ladder || !isWater(map, front)) {
    return false
  }
  // Over the square of water along the way, beside Link across it
  const vertical = isVertical(direction)
  map.ladder = { x: vertical ? link.x : front.x, y: vertical ? front.y : link.y, width: TILE_WIDTH, height: TILE_HEIGHT, vertical }
  return true
}

// On the ladder, Link only goes along it
export function canTurnOnLadder (map, link, direction) {
  return !map.ladder || !overlaps(map.ladder, link.getHitbox()) || map.ladder.vertical === isVertical(direction)
}

// Gone once Link went over it and is off it (see leaveLadder), or walked away from it without going over it
export function updateLadder (map, link) {
  const ladder = map.ladder
  if (!ladder) {
    return
  }
  const hitbox = link.getHitbox()
  if (overlaps(ladder, hitbox)) {
    ladder.used = true
    return
  }
  const touching = overlaps(ladder, { x: hitbox.x - 1, y: hitbox.y - 1, width: hitbox.width + 2, height: hitbox.height + 2 })
  if (ladder.used) {
    ladder.left = true
  } else if (!touching) {
    map.ladder = undefined
  }
}

// Link walks over it at his own speed (measured on the stream of 7,1, both ways: 1.5 NES pixels a frame). The frame
// after he is off it, it goes and he stands still (x = $70 twice going east, $50 going west). True then
export function leaveLadder (map) {
  if (!map.ladder?.left) {
    return false
  }
  map.ladder = undefined
  return true
}

export function drawLadder (context, map) {
  if (map.ladder) {
    resource.getSprite('item_ladder')?.draw(context, map.ladder.x, map.ladder.y, TILE_WIDTH, TILE_HEIGHT)
  }
}

// The raft (bank 4, $8F76): on two docks only, square 4 of a column of the screens 5,5 and 15,3. Link standing
// on the dock with the raft sails north, 1 NES pixel a frame, to the screen above; coming back from it at the top
// of the screen, he sails south to the dock. He does nothing else meanwhile. The raft is drawn 6 NES pixels
// below him
const RAFT_DOCKS = { '5,5': 8, '15,3': 6 }
const DOCK_LINE = 4
const RAFT_SPEED = NES_PIXEL
const RAFT_BELOW = 6 * NES_PIXEL

export function updateRaft (map, link) {
  const ride = link.raft
  if (ride && ride.map !== map) {
    // On the next screen (the screen changed under him)
    link.raft = undefined
    return
  }
  if (ride) {
    link.y += ride.direction === DIRECTION_NORTH ? -RAFT_SPEED : RAFT_SPEED
    if (ride.direction === DIRECTION_SOUTH && link.y >= ride.dockY) {
      link.y = ride.dockY
      link.raft = undefined
    }
    return
  }
  const column = map.type === MAP_TYPE_WORLD ? RAFT_DOCKS[`${map.column},${map.line}`] : undefined
  if (column === undefined || !link.inventory.raft || link.x !== map.x + column * TILE_WIDTH) {
    return
  }
  const dockY = map.y + DOCK_LINE * TILE_HEIGHT
  // Walking up onto the dock (his steps may pass the line by a pixel or two)
  if (link.y <= dockY && link.y > dockY - TILE_HEIGHT / 2 && link.direction === DIRECTION_NORTH) {
    link.y = dockY
    link.raft = { map, direction: DIRECTION_NORTH, dockY }
  } else if (link.y < dockY && link.direction === DIRECTION_SOUTH) {
    link.raft = { map, direction: DIRECTION_SOUTH, dockY }
  }
  if (link.raft) {
    link.stopWalking()
  }
}

export function drawRaft (context, link, offsetX, offsetY) {
  resource.getSprite('item_green_raft')?.draw(context, offsetX + link.x, offsetY + link.y + RAFT_BELOW, TILE_WIDTH, TILE_HEIGHT)
}
