'use strict'

import resource from '../../resource'
import { TILE_WIDTH, NES_PIXEL, DIRECTION_EAST, DIRECTION_WEST, DIRECTION_NORTH, DIRECTION_SOUTH } from '../../constant'
import { Enemy, DIRECTION_VECTORS, DIRECTIONS, STATE_HURT, drawImage, pick, randomInt, canWalkTo } from './common'
import { avoidObstacle } from './walker'

// The snake of level 2, read in the ROM (object $28, bank 4 $92D6): it walks on the grid at $20 (half a NES pixel a
// frame). Each time its timer ($28) is over, it starts again at a random byte & $3F, and on a point of the grid the
// rope takes a free way at random (bank 7, $F1DF). On a point of the grid, Link less than 8 NES pixels from its
// column, it turns to him, up or down; otherwise, less than 8 from its line, left or right: it then rushes at $60
// (1.5 NES pixel a frame, $03BC), without turning at random, until something in the way turns it (bank 7, $EFD0),
// when it walks again. One hit of the wooden sword kills it ($10); it takes half a heart from Link
const ROPE = { life: 1, contactDamage: 0.5 }
const WALK_SPEED = 1
const RUSH_SPEED = 3
const MAX_TIMER = 0x3f
const IN_LINE = 8 * NES_PIXEL
const GRID = TILE_WIDTH
// Its image changes every 8 display pixels it goes; facing left or right, the right one going up or down ($98 & 2)
const WALK_FRAME_PIXELS = 8
const STATE_WALKING = 'walking'

export class Rope extends Enemy {
  constructor (type, x, y, random = Math.random) {
    super(type, x, y, ROPE, random)
    this.direction = pick(random, DIRECTIONS)
    this.speed = WALK_SPEED
    this.timer = 0
    this.walkedPixels = 0
  }

  start (map) {
    this.setState(STATE_WALKING)
    this.turnAtRandom(map)
  }

  isOnGrid (map) {
    return (this.x - map.x) % GRID === 0 && (this.y - map.y) % GRID === 0
  }

  // A free way at random
  turnAtRandom (map) {
    const free = DIRECTIONS.filter(direction => canWalkTo(map, this.x, this.y, direction))
    if (free.length > 0) {
      this.direction = pick(this.random, free)
    }
  }

  // Link in line with it: it faces him and rushes
  lookForLink (link) {
    const dx = link.x - this.x
    const dy = link.y - this.y
    if (Math.abs(dx) < IN_LINE) {
      this.direction = dy >= 0 ? DIRECTION_SOUTH : DIRECTION_NORTH
    } else if (Math.abs(dy) < IN_LINE) {
      this.direction = dx >= 0 ? DIRECTION_EAST : DIRECTION_WEST
    } else {
      return
    }
    this.speed = RUSH_SPEED
  }

  // Walks again after being pushed back
  hit (link, weapon) {
    super.hit(link, weapon)
    if (this.state === STATE_HURT) {
      this.resumeState = STATE_WALKING
      this.speed = WALK_SPEED
    }
  }

  act (map, link) {
    const rushing = this.speed === RUSH_SPEED
    if (!rushing) {
      if (this.timer > 0) {
        this.timer--
      } else {
        this.timer = randomInt(this.random, 0, MAX_TIMER)
        if (this.isOnGrid(map)) {
          this.turnAtRandom(map)
        }
      }
    }
    for (let i = 0; i < this.speed; i++) {
      if (this.isOnGrid(map)) {
        if (this.speed === WALK_SPEED) {
          this.lookForLink(link)
        }
        const way = this.direction
        if (!avoidObstacle(this, map)) {
          return
        }
        // Turned by what is in the way: it walks again
        if (this.direction !== way) {
          this.speed = WALK_SPEED
          return
        }
      }
      const [dx, dy] = DIRECTION_VECTORS[this.direction]
      this.x += dx
      this.y += dy
      this.walkedPixels++
    }
  }

  drawBody (context) {
    const side = this.direction === DIRECTION_WEST ? 'west' : 'east'
    drawImage(context, resource.getSprite(`rope_${side}_move`), Math.floor(this.walkedPixels / WALK_FRAME_PIXELS) % 2, this.x, this.y, this.width, this.height)
  }
}
