'use strict'

import InputManager from '../service/input-manager'

// Keys of the screens around the game (title, choice of the game, game over menu): the player's keys for the given actions.
// Returns the function that stops listening
export function listenMenuKeys (handlers) {
  const listener = (e) => {
    for (const [action, handler] of Object.entries(handlers)) {
      if (e.code === InputManager.getBinding(action)) {
        e.preventDefault()
        handler()
        return
      }
    }
  }
  document.addEventListener('keydown', listener)

  return () => document.removeEventListener('keydown', listener)
}

// The player's keys held down, whatever the game does with them: { isHeld(action), stop() }
export function trackHeldKeys () {
  const held = new Set()
  const down = e => held.add(e.code)
  const up = e => held.delete(e.code)
  document.addEventListener('keydown', down)
  document.addEventListener('keyup', up)
  return {
    isHeld: action => held.has(InputManager.getBinding(action)),
    stop: () => {
      document.removeEventListener('keydown', down)
      document.removeEventListener('keyup', up)
    }
  }
}
